package com.hotelmanagement.hms.payment.web; import com.hotelmanagement.hms.payment.dto.*; import com.hotelmanagement.hms.payment.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.util.*; import java.math.*;
@RestController @RequestMapping("/api/v1/hotels/{hotel}/branches/{branch}/cashier-shifts") public class CashierShiftController {private final CashierShiftService s; public CashierShiftController(CashierShiftService s){this.s=s;} @GetMapping public Object list(@PathVariable UUID hotel,@PathVariable UUID branch){return s.list(hotel,branch);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public CashierShiftResponse open(@PathVariable UUID hotel,@PathVariable UUID branch,@Valid @RequestBody CashierShiftRequest q){return s.open(hotel,branch,q);} @PostMapping("/{id}/close") public CashierShiftResponse close(@PathVariable UUID hotel,@PathVariable UUID branch,@PathVariable UUID id,@RequestParam(defaultValue="0") BigDecimal expected,@RequestParam BigDecimal counted){return s.close(hotel,branch,id,expected,counted);} @PostMapping("/{id}/reconcile") @ResponseStatus(HttpStatus.NO_CONTENT) public void reconcile(@PathVariable UUID hotel,@PathVariable UUID branch,@PathVariable UUID id){s.reconcile(hotel,branch,id);} }

